class WorkerJSONEncoder(json.JSONEncoder):
    """
    JSON encoder that handles common Python types the standard encoder rejects.

    Extends :class:`json.JSONEncoder` so that payloads containing ``UUID``,
    ``datetime``/``date`` and ``Decimal`` values serialise cleanly:

      - ``UUID`` -> ``str(o)``
      - ``datetime`` / ``date`` -> ``o.isoformat()``
      - ``Decimal`` -> ``float(o)``

    Any other unsupported type falls through to the parent implementation,
    which raises ``TypeError``.
    """

    def default(self, o: Any) -> Any:
        if isinstance(o, UUID):
            return str(o)
        if isinstance(o, (datetime, date)):
            return o.isoformat()
        if isinstance(o, Decimal):
            return float(o)
        return super().default(o)


